/**
 * Android Material You (dynamic color) -> design-system tokens.
 *
 * Android 12+ (API 31) exposes the wallpaper-derived palette as five tonal
 * ramps of 13 stops each. A native shell reads them and hands the raw ramps
 * here; this module owns the mapping onto the DS surface/accent tokens, so the
 * translation is testable and platform-free.
 *
 * Stop numbering runs LIGHT to DARK: `0` is white, `1000` is black, and the
 * tone is `(1000 - stop) / 10`. That is the opposite of the DS accent scale,
 * where 50 is the lightest step.
 */

/** The stop indices Android publishes for every tonal palette. */
export const MATERIAL_YOU_STOPS = [
  0, 10, 50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 1000,
] as const

/** One tonal ramp: stop index -> "#rrggbb". */
export type MaterialYouRamp = Record<number, string>

/**
 * The five ramps, named as Android names them. `accent1` is the primary hue,
 * `neutral1` the surface ramp, `neutral2` a slightly desaturated companion used
 * for outlines.
 */
export interface MaterialYouPalette {
  accent1: MaterialYouRamp
  accent2: MaterialYouRamp
  accent3: MaterialYouRamp
  neutral1: MaterialYouRamp
  neutral2: MaterialYouRamp
}

export interface MaterialYouOptions {
  /**
   * The OLED overlay is active. Background and edge chrome are then left to
   * `.dark.extra-dark`'s true black rather than taking a wallpaper tint --
   * black is what switches the pixels off, which is the whole point of that
   * theme. Every other surface still maps.
   */
  extraDark?: boolean
}

const HEX = /^#[0-9a-f]{6}$/i

/**
 * The midpoint of two ramp stops.
 *
 * The published tones step in tens, which is coarser than the text ladder
 * needs at its bottom rung: the stop below `secondary` lands on `secondary`
 * itself, and the one below that falls under the AA floor. Muted is the
 * halfway tone, which clears AA against both the page and the card while
 * staying a visible step short of secondary.
 */
function midpoint(a: string, b: string): string {
  const channel = (h: string, i: number) => parseInt(h.slice(1 + i * 2, 3 + i * 2), 16)
  const out = [0, 1, 2].map((i) => Math.round((channel(a, i) + channel(b, i)) / 2))
  return `#${out.map((v) => v.toString(16).padStart(2, '0')).join('')}`
}

/**
 * True when `value` looks like every ramp Android should have sent. A shell on
 * a device below API 31, or one whose read threw, hands over nothing rather
 * than a partial palette, and a half-mapped theme is worse than none.
 */
export function isMaterialYouPalette(value: unknown): value is MaterialYouPalette {
  if (typeof value !== 'object' || value === null) return false
  const ramps = ['accent1', 'accent2', 'accent3', 'neutral1', 'neutral2'] as const
  return ramps.every((name) => {
    const ramp = (value as Record<string, unknown>)[name]
    if (typeof ramp !== 'object' || ramp === null) return false
    const record = ramp as Record<string, unknown>
    return MATERIAL_YOU_STOPS.every((stop) => {
      const hex = record[stop]
      return typeof hex === 'string' && HEX.test(hex)
    })
  })
}

/**
 * The CSS custom properties a palette resolves to, as a plain map.
 *
 * The DS surface ladder runs page -> card -> muted, page being the DARKEST rung
 * in light mode and the darkest in dark mode too (muted is the top rung in
 * both). The stops below keep that ordering, so a component that relies on a
 * card standing out from the page still gets separation whatever the wallpaper
 * is.
 *
 * `--color-neutral-900/800/700` are re-pointed alongside the surfaces they are
 * equal to by construction. `surface-contrast.test.ts` pins that equality on
 * the token source; a component reaching for a raw neutral step as a "subtle
 * plane" (Badge, EmptyState, the nav highlights) would otherwise keep its
 * built-in grey while everything under it took the wallpaper tint.
 *
 * Accent is a single theme-independent token, so it takes the M3 primary role
 * for the ACTIVE theme: tone 40 on light, tone 80 on dark. Callers pass it to
 * `applyAccentColor`, which derives the rest of the scale and the contrast-safe
 * foreground.
 *
 * Text follows the surfaces from the same ramps. Leaving it on the built-in
 * greys puts a fixed near-black or near-white over a tinted surface, which
 * reads as unthemed next to everything around it, and `--wj-focus-ring-color`
 * aliases the primary text token, so the focus ring tracks it too.
 */
export function materialYouTokens(
  palette: MaterialYouPalette,
  { extraDark = false }: MaterialYouOptions = {},
): Record<string, string> {
  const { neutral1, neutral2 } = palette
  const tokens: Record<string, string> = {
    '--color-background-light': neutral1[50],
    '--color-surface-light': neutral1[10],
    '--color-surface-muted-light': neutral1[0],
    '--color-border-light': neutral2[100],

    '--color-surface-dark': neutral1[800],
    '--color-surface-muted-dark': neutral1[700],
    '--color-border-dark': neutral2[600],

    '--color-neutral-800': neutral1[800],
    '--color-neutral-700': neutral2[600],

    // Text takes the M3 on-surface roles, so a wallpaper that shifts the
    // surfaces carries its text with it. Unaffected by `extraDark`, which
    // leaves the text tokens alone.
    //
    // The secondary stop is chosen to land on the CONTRAST the built-in tokens
    // carry against their own page rather than on the neighbouring M3 tone, and
    // muted takes the midpoint between secondary and the stop nearer the
    // surface -- see `midpoint`, which exists because the published tones are
    // too coarse for that rung.
    '--color-text-primary-light': neutral1[900],
    '--color-text-secondary-light': neutral2[600],
    '--color-text-muted-light': midpoint(neutral2[600], neutral2[500]),
    '--color-text-primary-dark': neutral1[100],
    '--color-text-secondary-dark': neutral2[300],
    '--color-text-muted-dark': midpoint(neutral2[300], neutral2[400]),
  }
  // Under the OLED overlay the page stays true black, and so does
  // `--color-neutral-900`, which IS the page colour. `--wj-chrome-base` is
  // never written here: in ordinary dark it resolves through
  // `--color-surface-dark` and follows the mapping on its own, and under
  // `.dark.extra-dark` the class pins it to black, which an inline write would
  // outrank.
  if (!extraDark) {
    tokens['--color-background-dark'] = neutral1[900]
    tokens['--color-neutral-900'] = neutral1[900]
  }
  return tokens
}

/** The accent seed for a resolved theme: the M3 primary role for that theme. */
export function materialYouAccent(palette: MaterialYouPalette, isDark: boolean): string {
  return isDark ? palette.accent1[200] : palette.accent1[600]
}

/**
 * The page colour a palette resolves to per theme, for a caller that has to
 * hand a concrete hex to native chrome (`useTheme`'s `themeColors`).
 *
 * `extraDark` is deliberately absent: the OLED page is black and is not ours to
 * move.
 */
export function materialYouThemeColors(palette: MaterialYouPalette): {
  light: string
  dark: string
} {
  return { light: palette.neutral1[50], dark: palette.neutral1[900] }
}

/** Stop set for `writableTokenNames` to enumerate token NAMES from. */
const BLANK_PALETTE: MaterialYouPalette = (() => {
  const ramp: MaterialYouRamp = {}
  for (const stop of MATERIAL_YOU_STOPS) ramp[stop] = '#000000'
  return { accent1: ramp, accent2: ramp, accent3: ramp, neutral1: ramp, neutral2: ramp }
})()

/**
 * Every custom property this module can write under ANY options. A token the
 * CURRENT options drop -- the page under the OLED overlay -- has to be removed
 * rather than left at its last value: these are written inline, and an inline
 * write outranks the `.dark.extra-dark` rule it would otherwise be hiding.
 */
function writableTokenNames(): string[] {
  return Object.keys(materialYouTokens(BLANK_PALETTE))
}

/**
 * Writes the mapped tokens onto `:root` as inline custom properties.
 *
 * Inline is what lets a mapped surface outrank the `.dark.extra-dark` overlay
 * while the two tokens that overlay owns -- the page and the edge chrome -- are
 * left to it, the page by being removed here and `--wj-chrome-base` by never
 * being written at all.
 */
export function applyMaterialYou(
  palette: MaterialYouPalette,
  options: MaterialYouOptions = {},
): void {
  const root = document.documentElement
  const tokens = materialYouTokens(palette, options)
  for (const name of writableTokenNames()) {
    const value = tokens[name]
    if (value) root.style.setProperty(name, value)
    else root.style.removeProperty(name)
  }
}

/** Removes every token `applyMaterialYou` writes, back to the stylesheet. */
export function clearMaterialYou(): void {
  const root = document.documentElement
  for (const name of writableTokenNames()) root.style.removeProperty(name)
}
